"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/** Errors a Form found, keyed by the id of the control they belong to. */
const FieldErrors = React.createContext<Record<string, string>>({})
const FieldErrorsProvider = FieldErrors.Provider

type FieldContext = { id: string; hintId?: string; errorId?: string; invalid: boolean; maxLength?: number }
const FieldCtx = React.createContext<FieldContext | null>(null)

/** What a control inside a Field needs: its id, what describes it, whether it's wrong. Empty outside a Field. */
function useFieldControl() {
  const ctx = React.useContext(FieldCtx)
  return {
    id: ctx?.id,
    maxLength: ctx?.maxLength,
    "aria-invalid": ctx?.invalid ? (true as const) : undefined,
    "aria-describedby": [ctx?.hintId, ctx?.errorId].filter(Boolean).join(" ") || undefined,
  }
}

type FieldProps = Omit<React.ComponentProps<"div">, "id"> & {
  label?: React.ReactNode
  hint?: React.ReactNode
  /** What to fix, in plain words. Turns the baseline crimson and hangs the message from it. */
  error?: React.ReactNode
  /** Show how much is typed, "12 / 40", while the field has focus. */
  count?: boolean
  maxLength?: number
  /** The control's id. Made for you when omitted. */
  id?: string
}

/** One control on a baseline. Wraps an Input, Textarea, InputGroup or InputOTP and wires label, hint and error to it. */
function Field({ label, hint, error, count, maxLength, id, className, children, onInput, ...props }: FieldProps) {
  const made = React.useId()
  const controlId = id ?? made
  const formErrors = React.useContext(FieldErrors)
  const message = error ?? formErrors[controlId]
  const root = React.useRef<HTMLDivElement>(null)
  const [typed, setTyped] = React.useState(0)
  React.useEffect(() => {
    const el = root.current?.querySelector<HTMLInputElement>("input, textarea")
    if (count && el) setTyped(el.value.length)
  }, [count])

  const ctx: FieldContext = {
    id: controlId,
    hintId: hint ? `${controlId}-hint` : undefined,
    errorId: message ? `${controlId}-error` : undefined,
    invalid: Boolean(message),
    maxLength,
  }

  return (
    <FieldCtx.Provider value={ctx}>
      <div
        ref={root}
        data-slot="field"
        className={cn("db-field", className)}
        onInput={(e) => {
          onInput?.(e)
          if (count && (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement)) setTyped(e.target.value.length)
        }}
        {...props}
      >
        {label ? (
          <label data-slot="field-label" className="db-label" htmlFor={controlId}>
            {label}
          </label>
        ) : null}
        {count ? (
          <span data-slot="field-count" className="db-field-count" aria-hidden="true">
            {typed}
            {maxLength ? ` / ${maxLength}` : null}
          </span>
        ) : null}
        {children}
        {hint ? (
          <p data-slot="field-hint" id={ctx.hintId} className="db-field-hint">
            {hint}
          </p>
        ) : null}
        {message ? <FieldError id={ctx.errorId}>{message}</FieldError> : null}
      </div>
    </FieldCtx.Provider>
  )
}

/** The callout: a pill on a leader line, hung from the baseline it's about. */
function FieldError({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="field-error" className={cn("db-field-error", className)} {...props} />
}

type Control<T extends HTMLElement> = React.ComponentProps<T extends HTMLTextAreaElement ? "textarea" : "input">

/**
 * The accent line grows out from where you touched the line; for the keyboard,
 * from where the line starts (the right in a right-to-left page). Sets --o on `line`.
 */
function useLineOrigin<T extends HTMLInputElement | HTMLTextAreaElement>(line: (el: T) => HTMLElement, { onPointerDown, onFocus }: Control<T>) {
  const touched = React.useRef(false)
  return {
    onPointerDown(e: React.PointerEvent<T>) {
      onPointerDown?.(e as never)
      const r = e.currentTarget.getBoundingClientRect()
      line(e.currentTarget).style.setProperty("--o", `${Math.round(((e.clientX - r.left) / r.width) * 100)}%`)
      touched.current = true
    },
    onFocus(e: React.FocusEvent<T>) {
      onFocus?.(e as never)
      if (!touched.current) line(e.currentTarget).style.setProperty("--o", getComputedStyle(e.currentTarget).direction === "rtl" ? "100%" : "0%")
      touched.current = false
    },
  }
}

/** Your words arrive in italic; the placeholder stays in our voice, in pencil. Works alone or inside a Field. */
function Input({ className, ...props }: React.ComponentProps<"input">) {
  const field = useFieldControl()
  const origin = useLineOrigin<HTMLInputElement>((el) => el, props)
  return (
    <input
      data-slot="input"
      className={cn("db-input", className)}
      {...props}
      id={props.id ?? field.id}
      maxLength={props.maxLength ?? field.maxLength}
      aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
      aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
      {...origin}
    />
  )
}

/** Ruled like paper: the lines sit on the text's baselines and scroll with it. */
function Textarea({ className, ...props }: React.ComponentProps<"textarea">) {
  const field = useFieldControl()
  const origin = useLineOrigin<HTMLTextAreaElement>((el) => el, props)
  return (
    <textarea
      data-slot="textarea"
      className={cn("db-input", className)}
      {...props}
      id={props.id ?? field.id}
      maxLength={props.maxLength ?? field.maxLength}
      aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
      aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
      {...origin}
    />
  )
}

export { Field, FieldError, FieldErrorsProvider, Input, Textarea, useFieldControl, useLineOrigin, type FieldProps }

@layer components {
  /* ── db-field ── no box, only a baseline; your words arrive in italic */
  .db-field { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; row-gap: var(--db-space-1); }
  .db-field > .db-label { grid-column: 1; }
  .db-field-count { grid-column: 2; font-size: var(--db-pp); color: var(--db-pencil); font-variant-numeric: tabular-nums; opacity: 0; transition: opacity var(--db-allegro); }
  .db-field:focus-within .db-field-count, .db-field[data-force~="focus"] .db-field-count { opacity: 1; }
  .db-field > .db-input { grid-column: 1 / -1; }

  /* The control itself. Works alone, or inside a Field. */
  .db-input {
    appearance: none; width: 100%; margin: 0; border: 0; border-radius: 0; outline: 0;
    padding: 0.3em 0 0.42em;
    background:
      linear-gradient(var(--db-accent), var(--db-accent)) no-repeat var(--o, 0%) 100% / 0% var(--db-stroke),
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
    color: var(--db-ink);
    font-family: var(--db-expression); font-style: italic; font-weight: 400;
    font-size: calc(var(--db-mp) * var(--db-expression-scale)); line-height: 1.3;
    transition: background-size var(--db-moderato) var(--db-exhale);
  }
  .db-input::placeholder { font-family: var(--db-voice); font-style: normal; font-size: var(--db-mp); color: var(--db-pencil); opacity: 1; transition: color var(--db-moderato); }
  .db-input:focus::placeholder { color: color-mix(in srgb, var(--db-pencil) 55%, transparent); } /* it steps back when you arrive */
  .db-input:focus,
  .db-field[data-force~="focus"] > .db-input { background-size: 100% var(--db-stroke), 100% var(--db-hairline); }
  .db-field[data-force~="focus"] { outline: 0; }
  .db-input[aria-invalid="true"] { background-image: linear-gradient(var(--db-signal), var(--db-signal)), linear-gradient(var(--db-signal), var(--db-signal)); }
  .db-input:disabled {
    color: var(--db-pencil); cursor: not-allowed;
    background-image: none, repeating-linear-gradient(90deg, var(--db-rule-strong) 0 2px, transparent 2px 6px);
  }
  textarea.db-input {
    --lh: 2.25rem;
    min-height: calc(var(--lh) * 4); padding: 0; resize: vertical;
    line-height: var(--lh);
    background:
      linear-gradient(var(--db-accent), var(--db-accent)) no-repeat var(--o, 0%) 100% / 0% var(--db-stroke),
      repeating-linear-gradient(transparent 0 calc(var(--lh) - 1px), var(--db-rule-strong) calc(var(--lh) - 1px) var(--lh)) 0 var(--db-rule-shift, -0.3rem) / 100% var(--lh);
    background-attachment: local;
  }
  textarea.db-input:focus,
  .db-field[data-force~="focus"] > textarea.db-input { background-size: 100% var(--db-stroke), 100% var(--lh); }
  textarea.db-input[aria-invalid="true"] {
    background-image:
      linear-gradient(var(--db-signal), var(--db-signal)),
      repeating-linear-gradient(transparent 0 calc(var(--lh) - 1px), var(--db-signal) calc(var(--lh) - 1px) var(--lh));
  }

  .db-field-hint, .db-field-error { grid-column: 1 / -1; margin-top: var(--db-space-1); font-size: var(--db-pp); line-height: var(--db-pp-lh); }
  .db-field-hint { color: var(--db-pencil); }
  /* An error is a callout, as Weingart set them: a pill on a leader line,
     hung from the baseline it's about. */
  .db-field-error {
    position: relative; justify-self: start; margin-top: var(--db-space-5);
    padding: 0.3em 0.9em 0.36em; border-radius: 1em;
    box-shadow: inset 0 0 0 var(--db-hairline) var(--db-signal); color: var(--db-signal);
    animation: db-callout var(--db-moderato) var(--db-exhale) 220ms backwards;
  }
  .db-field-error::before { content: ""; position: absolute; inset-inline-start: 1.1em; bottom: 100%; width: var(--db-hairline); height: var(--db-space-5); background: var(--db-signal); transform-origin: top; animation: db-draw-y var(--db-moderato) var(--db-breath) 60ms backwards; }
  .db-field-error::after { content: ""; position: absolute; inset-inline-start: calc(1.1em - 2px); bottom: calc(100% + var(--db-space-5) - 2.5px); width: 5px; height: 5px; border-radius: 50%; background: var(--db-signal); animation: db-land var(--db-moderato) var(--db-spiccato) backwards; }
  @keyframes db-callout { from { color: transparent; box-shadow: inset 0 0 0 var(--db-hairline) transparent; } }
}
